using BenchmarkDotNet.Attributes;
using Marimo.Parser;
using Marimo.Kotowari.Core;
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Text.Json;

namespace Marimo.Kotowari.Benchmarks;

[MemoryDiagnoser]
public class JsonStreamBenchmarks
{
    private byte[] _input = null!;

    [GlobalSetup]
    public void Setup()
        => _input = File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Data", "test.json"));

    public static void Validate()
    {
        var benchmarks = new JsonStreamBenchmarks();
        benchmarks.Setup();
        var text = Encoding.UTF8.GetString(benchmarks._input);
        using var expected = JsonDocument.Parse(benchmarks._input);

        var actual = ParseAndVerifyFullConsumption(text);
        AssertEquivalent(expected.RootElement, actual);

        var nodeCount = CountNodes(actual);
        if (nodeCount != 100_001)
        {
            throw new InvalidOperationException($"Expected 100,001 nodes, got {nodeCount:N0}.");
        }

        Console.WriteLine($"Input: {benchmarks._input.Length:N0} bytes; {text.Length:N0} characters");
        Console.WriteLine($"StringInput consumes the full input and produces the expected JSON tree ({nodeCount:N0} nodes).");
    }

    [Benchmark]
    public JSONObject StringInput()
    {
        using var source = new MemoryStream(_input, writable: false);
        using var buffer = new MemoryStream(_input.Length);
        source.CopyTo(buffer);
        var bytes = buffer.GetBuffer().AsSpan(0, checked((int)buffer.Length));
        return JSON.Parse(Encoding.UTF8.GetString(bytes));
    }

    private static JSONObject ParseAndVerifyFullConsumption(string text)
    {
        var cursor = new Cursol(text);
        var rootParser = typeof(JSON).GetField("JObject", BindingFlags.NonPublic | BindingFlags.Static)?.GetValue(null)
            ?? throw new InvalidOperationException("The JSON root parser could not be found.");
        var parse = rootParser.GetType().GetMethod("Parse", BindingFlags.Public | BindingFlags.Instance)
            ?? throw new InvalidOperationException("The parser entry point could not be found.");
        var result = parse.Invoke(rootParser, [cursor])
            ?? throw new InvalidOperationException("The JSON parser returned no result.");
        var resultType = result.GetType();
        if ((bool)(resultType.GetProperty("IsSuccess")?.GetValue(result)
            ?? throw new InvalidOperationException("The parse status could not be read.")) is false)
        {
            throw new InvalidOperationException("The JSON parser rejected the input.");
        }

        var parsedCursor = (Cursol)(resultType.GetProperty("Cursol")?.GetValue(result)
            ?? throw new InvalidOperationException("The parse cursor could not be read."));
        if (parsedCursor.Index != text.Length)
        {
            throw new InvalidOperationException($"The parser consumed {parsedCursor.Index:N0} of {text.Length:N0} characters.");
        }

        return (JSONObject)(resultType.GetProperty("Parsed")?.GetValue(result)
            ?? throw new InvalidOperationException("The parsed JSON object could not be read."));
    }

    private static int CountNodes(IJSONValue value)
    {
        if (value is JSONObject obj)
        {
            var count = 1;
            foreach (var child in obj.Pairs.Values)
            {
                count += CountNodes(child);
            }
            return count;
        }

        if (value is JSONArray array)
        {
            var count = 1;
            foreach (var child in array.Elements)
            {
                count += CountNodes(child);
            }
            return count;
        }

        return 1;
    }

    private static void AssertEquivalent(JsonElement expected, IJSONValue actual)
    {
        switch (expected.ValueKind)
        {
            case JsonValueKind.Object:
                if (actual is not JSONObject obj)
                {
                    throw new InvalidOperationException("The parser result is not an object.");
                }

                foreach (var property in expected.EnumerateObject())
                {
                    if (!obj.Pairs.TryGetValue(property.Name, out var child))
                    {
                        throw new InvalidOperationException($"The parser result has no '{property.Name}' property.");
                    }

                    AssertEquivalent(property.Value, child);
                }

                if (obj.Pairs.Count != expected.EnumerateObject().Count())
                {
                    throw new InvalidOperationException("The parser result has a different object member count.");
                }
                return;

            case JsonValueKind.Array:
                if (actual is not JSONArray array)
                {
                    throw new InvalidOperationException("The parser result is not an array.");
                }

                var index = 0;
                foreach (var item in expected.EnumerateArray())
                {
                    if (index >= array.Elements.Count)
                    {
                        throw new InvalidOperationException("The parser result has too few array elements.");
                    }

                    AssertEquivalent(item, array.Elements[index]);
                    index++;
                }

                if (index != array.Elements.Count)
                {
                    throw new InvalidOperationException("The parser result has too many array elements.");
                }
                return;

            case JsonValueKind.String:
                AssertLiteral(actual, LiteralType.String, expected.GetString());
                return;

            case JsonValueKind.Number:
                AssertLiteral(actual, LiteralType.Number, expected.GetRawText());
                return;

            case JsonValueKind.True:
                AssertLiteral(actual, LiteralType.Boolean, "true");
                return;

            case JsonValueKind.False:
                AssertLiteral(actual, LiteralType.Boolean, "false");
                return;

            case JsonValueKind.Null:
                AssertLiteral(actual, LiteralType.Null, null);
                return;

            default:
                throw new InvalidOperationException($"Unsupported JSON kind: {expected.ValueKind}.");
        }
    }

    private static void AssertLiteral(IJSONValue actual, LiteralType type, string? value)
    {
        if (actual is not JSONLiteral literal || literal.ValueType != type || literal.Value != value)
        {
            throw new InvalidOperationException($"Unexpected JSON literal; expected {type} '{value}'.");
        }
    }
}

using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Running;
using System;

namespace Marimo.Kotowari.Benchmarks;

public static class Program
{
    public static void Main(string[] args)
    {
        if (args is ["--validate"])
        {
            JsonStreamBenchmarks.Validate();
