        Job=([regex]::Match($stdout,'(?m)^// Job: (?<job>.+)$').Groups['job'].Value); TieredPGO=1; Affinity=$affinity
        ProcessId=$processId; StartUTC=$utc.ToString('o'); WallSeconds=$elapsedSeconds
        PowerShell=$PSVersionTable.PSVersion.ToString()
        ResumedExistingOutput=$reuseOutput
        InputBytes=(Get-Item -LiteralPath $inputPath).Length; InputSHA256=$expectedInputHash
        AssemblySHA256=$afterHash; MeasurementHostAssemblySHA256=(Get-FileHash -LiteralPath $measurementHost -Algorithm SHA256).Hash
        LibraryDLLSHA256=$libraryHash; JsonDLLSHA256=$jsonHash
        ChildLibraryDLLSHA256=$libraryHash; ChildJsonDLLSHA256=$jsonHash
        DLLManifestSHA256=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash
        SourceFiles=$sourceFiles
    }
    $record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $summaryPath -Encoding utf8
    Write-Output ('Completed {0}: mean {1:F3} ms, {2} Actual/{3} Result.' -f $runName,($record.MeanNs/1e6),$record.ActualCount,$record.ResultCount)
}
