param(
    [Parameter(Mandatory)][ValidateSet('before','after')][string]$Stage
)

$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System.Runtime.InteropServices;
[StructLayout(LayoutKind.Sequential)]
public struct StringRecoveryPowerStatus {
    public byte ACLineStatus;
    public byte BatteryFlag;
    public byte BatteryLifePercent;
    public byte SystemStatusFlag;
    public uint BatteryLifeTime;
    public uint BatteryFullLifeTime;
}
public static class StringRecoveryPowerStatusApi {
    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern bool GetSystemPowerStatus(out StringRecoveryPowerStatus status);
}
'@

$status = New-Object StringRecoveryPowerStatus
if (-not [StringRecoveryPowerStatusApi]::GetSystemPowerStatus([ref]$status)) {
    throw "GetSystemPowerStatus failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
}
$powerScheme = (powercfg.exe /getactivescheme) -join ' '
$sampleStart = [DateTime]::UtcNow
$first = @(Get-Process -Name dotnet -ErrorAction SilentlyContinue | Select-Object Id,CPU,StartTime)
$cimFirst = @(Get-CimInstance -ClassName Win32_Process | Select-Object ProcessId,Name,KernelModeTime,UserModeTime)
Start-Sleep -Seconds 3
$sampleEnd = [DateTime]::UtcNow
$second = @(Get-Process -Name dotnet -ErrorAction SilentlyContinue | Select-Object Id,CPU,StartTime)
$cimSecond = @(Get-CimInstance -ClassName Win32_Process | Select-Object ProcessId,Name,KernelModeTime,UserModeTime)
$cpuActivity = @(
    foreach ($process in $second) {
        $previous = $first | Where-Object Id -eq $process.Id | Select-Object -First 1
        if ($previous -and $null -ne $process.CPU -and $null -ne $previous.CPU -and $process.CPU -gt $previous.CPU) {
            [ordered]@{ ProcessId=$process.Id; DeltaCpuSeconds=($process.CPU-$previous.CPU) }
        }
    }
)
$cimCpuActivity = @(
    foreach ($process in $cimSecond) {
        $previous = $cimFirst | Where-Object ProcessId -eq $process.ProcessId | Select-Object -First 1
        if ($previous -and $null -ne $process.KernelModeTime -and $null -ne $process.UserModeTime) {
            $delta = ([double]$process.KernelModeTime + [double]$process.UserModeTime) - ([double]$previous.KernelModeTime + [double]$previous.UserModeTime)
            if ($delta -gt 0) { [ordered]@{ ProcessId=$process.ProcessId; Name=$process.Name; DeltaCpuSeconds=($delta / 10000000) } }
        }
    }
)
$record = [ordered]@{
    Stage=$Stage
    TimestampUTC=[DateTime]::UtcNow.ToString('o')
    SampleStartUTC=$sampleStart.ToString('o')
    SampleEndUTC=$sampleEnd.ToString('o')
    ACLineStatus=[int]$status.ACLineStatus
    ACLineMeaning='1=online, 0=offline, 255=unknown'
    BatterySaver=[int]$status.SystemStatusFlag
    BatterySaverMeaning='1=active, 0=inactive'
    BatteryFlag=[int]$status.BatteryFlag
    BatteryLifePercent=[int]$status.BatteryLifePercent
    PowerScheme=$powerScheme
    DotnetCpuActivityWindowSeconds=3
    ActiveDotnetProcesses=$cpuActivity
    ActiveCimProcesses=$cimCpuActivity
}
$path = Join-Path $PSScriptRoot 'environment.json'
if (Test-Path -LiteralPath $path) {
    $records = @(Get-Content -Raw -LiteralPath $path | ConvertFrom-Json)
} else {
    $records = @()
}
$records += [pscustomobject]$record
$records | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $path -Encoding utf8
Write-Output ('{0}: ACLine={1}, BatterySaver={2}, PowerScheme={3}, dotnetCPU-active={4}' -f $Stage,$record.ACLineStatus,$record.BatterySaver,$record.PowerScheme,$cpuActivity.Count)
